        refusal.textContent = d.refusal_reason || 'Execution halted per gate constraints';
        details.textContent = `Task: ${d.task_type.toUpperCase()} | Required: ${d.required_inputs_count} image(s), Provided: ${d.provided_inputs_count}`;
    } else {
        refusal.style.display = 'none';
        if (d.task_type.includes('sar')) {
            banner.classList.add('sar');
            details.innerHTML = `<div><b>SAR ANALYSIS &mdash; Deterministic Radar Feature Pathway</b></div><div style="font-size:12px; color:var(--text-secondary); margin-top:2px;">No SAR-native VLM available on this host. Answer generated from measured radar features.</div><div style="font-size:12px; margin-top:4px;">Task Intent: ${d.task_type.toUpperCase()} | Target Modalities: ${d.input_modalities.join(', ')}</div>`;
        } else {
            details.textContent = `Task Intent: ${d.task_type.toUpperCase()} | Target Modalities: ${d.input_modalities.join(', ')}`;
        }
    }

    // Tool Sequence & Execution Status (Honest distinction between EXECUTED vs NOT_IMPLEMENTED)
    if (d.tools_executed && d.tools_executed.length) {
        tools.innerHTML = d.tools_executed.map(te => {
            const cls = te.status === 'EXECUTED' ? 'status-ready' : (te.status === 'NOT_IMPLEMENTED' ? 'status-warn' : 'status-subtle');
            return `<span class="tool-pill ${cls}" title="${te.notes || te.status}">${te.tool_name}: ${te.status}</span>`;
        }).join('');
    } else if (d.tool_sequence && d.tool_sequence.length) {
        tools.innerHTML = d.tool_sequence.map(tool => `<span class="tool-pill status-subtle">${tool}: SCHEDULED</span>`).join('');
    } else {
        tools.innerHTML = `<span style="color:var(--text-muted); font-size:12px;">No tools scheduled (Refusal pathway)</span>`;
    }

    // Honest Mechanism & Answer Display
    const existingCard = document.getElementById('resultMechanismCard');
    if (existingCard) existingCard.remove();

    if (resp.result) {
        const resDiv = document.createElement('div');
        resDiv.id = 'resultMechanismCard';
        resDiv.className = 'mechanism-card';
        const mech = resp.result.mechanism || 'None';
        const vlm = resp.result.model || 'Not Used';
        resDiv.innerHTML = `
            <div><b>Mechanism:</b> <code>${mech}</code> | <b>VLM:</b> <code>${vlm}</code></div>
            <div><b>Status:</b> <span class="status-pill ${resp.result.status === 'COMPLETED' ? 'ready' : 'warn'}">${resp.result.status}</span></div>
            ${resp.result.answer ? `<div style="margin-top:6px; font-style:italic; color:var(--text-primary);">${resp.result.answer}</div>` : ''}
            ${resp.result.limitations && resp.result.limitations.length ? `<div style="color:var(--status-warn); font-size:11px; margin-top:4px;">Limitations: ${resp.result.limitations.join('; ')}</div>` : ''}
        `;
        banner.appendChild(resDiv);
    }

    // Execution Trace
    traceSteps.innerHTML = t.steps.map(step => {
        const isOk = step.status === 'completed';
        const icon = isOk ? '✓' : '✗';
        const iconCls = isOk ? 'ok' : 'fail';
        return `
            <div class="trace-step">
                <span class="trace-icon ${iconCls}">${icon}</span>
                <div class="trace-content">
                    <div class="trace-step-name">${step.name}</div>
                    ${step.details ? `<div class="trace-step-details">${step.details}</div>` : ''}
                </div>
            </div>
        `;
    }).join('');

    // Smooth scroll to results
    container.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

