async function showCapabilitiesModal() {
    const modal = document.getElementById('capabilitiesModal');
    const list = document.getElementById('capabilitiesList');
    modal.classList.add('active');
    list.innerHTML = `<div class="spinner"></div>`;

    try {
        const res = await fetch(`${API}/api/capabilities`);
        const data = await res.json();
        list.innerHTML = Object.entries(data.capabilities).map(([key, cap]) => `
            <div class="cap-row">
                <div>
                    <div class="cap-title">${cap.name}</div>
                    <div class="cap-desc">${cap.description}</div>
                    <div style="font-size:11px; color:var(--text-muted); margin-top:4px;">
                        Engine: <b>${cap.primary_engine}</b> ${cap.fallback_engine ? `| Fallback: ${cap.fallback_engine}` : ''}
                    </div>
                    <div style="font-size:11px; color:var(--text-secondary); margin-top:2px;">
                        Routing: <b>${cap.routing_readiness || 'N/A'}</b> | Execution: <b>${cap.execution_readiness || 'N/A'}</b> | Model: <b>${cap.model_availability || 'N/A'}</b>
                    </div>
                    ${cap.license_note ? `<div style="font-size:11px; color:var(--status-warn); margin-top:2px;">License: ${cap.license_note}</div>` : ''}
                </div>
                <div>
                    <span class="status-pill ${cap.status === 'READY' ? 'ready' : (cap.status === 'BLOCKED_LICENSE' ? 'error' : 'warn')}">${cap.status}</span>
                </div>
            </div>
        `).join('');
    } catch (e) {
        list.innerHTML = `<div style="color:var(--status-error)">Failed to load capabilities.</div>`;
    }

